import type { HttpClient } from '../http/types';
import type { AuthStore } from '../stores/authStore';
import type { AuthAdapter, LoginCredentials } from './types';

export interface AuthService {
  login: (credentials: LoginCredentials) => Promise<void>;
  logout: () => Promise<void>;
  /** Tải lại user + quyền (vd sau khi đổi role). */
  reloadSession: () => Promise<void>;
  /** Trả access token mới, hoặc null nếu không refresh được. */
  refresh: () => Promise<string | null>;
}

/** Ghép adapter + store. Hàm thuần, không side effect (an toàn với StrictMode). */
export const createAuthService = (adapter: AuthAdapter, store: AuthStore): AuthService => {
  const reloadSession = async () => {
    try {
      store.getState().setSession(await adapter.getSession());
    } catch (error) {
      store.getState().clear();
      throw error;
    }
  };

  const refresh = async () => {
    const current = store.getState().tokens;

    if (!adapter.refresh || !current?.refreshToken) return null;

    try {
      const tokens = await adapter.refresh(current.refreshToken);

      store.getState().setTokens({ ...tokens, refreshToken: tokens.refreshToken ?? current.refreshToken });

      return tokens.accessToken;
    } catch {
      return null;
    }
  };

  return {
    login: async credentials => {
      store.getState().setTokens(await adapter.login(credentials));
      await reloadSession();
    },
    logout: async () => {
      const tokens = store.getState().tokens;

      try {
        await adapter.logout?.(tokens);
      } catch {
        // Logout phía server lỗi vẫn phải xoá phiên phía client.
      } finally {
        store.getState().clear();
      }
    },
    reloadSession,
    refresh,
  };
};

/** Cho http client biết lấy token ở đâu, refresh thế nào, hết phiên thì làm gì. */
export const bindHttpAuth = (http: HttpClient, store: AuthStore, service: AuthService, adapter: AuthAdapter) => {
  http.setAuthHandlers({
    getAccessToken: () => store.getState().tokens?.accessToken,
    refreshAccessToken: adapter.refresh ? service.refresh : undefined,
    onUnauthorized: () => store.getState().clear(),
  });

  return () => http.setAuthHandlers(undefined);
};
